-- Script SQL Server - Marvel Characters Database
-- Crear tabla
IF OBJECT_ID('marvel_characters', 'U') IS NOT NULL
    DROP TABLE marvel_characters;

CREATE TABLE marvel_characters (
    page_id INT PRIMARY KEY,
    name NVARCHAR(500),
    urlslug NVARCHAR(500),
    ID NVARCHAR(100),
    ALIGN NVARCHAR(100),
    EYE NVARCHAR(100),
    HAIR NVARCHAR(100),
    SEX NVARCHAR(100),
    GSM NVARCHAR(100),
    ALIVE NVARCHAR(100),
    APPEARANCES INT,
    FIRST_APPEARANCE NVARCHAR(50),
    Year INT
);

